public static DataSet createLagData(DataSet data, int numLags) {
    List<Node> variables = data.getVariables();

    // Colons in the input variable names would collide with the lag suffix convention
    // ("X:1" for X lagged once). Formerly such names either put variables in the wrong
    // knowledge tiers or caused the lagging to be skipped silently; better to say so.
    for (Node node : variables) {
        if (node.getName().indexOf(':') >= 0) {
            throw new IllegalArgumentException(
                    "Cannot create lagged data: variable name \"" + node.getName()
                    + "\" contains a colon. Tetrad reserves the colon in variable names"
                    + " for lag suffixes, as in X:1 for X lagged once, so variables in"
                    + " data to be lagged may not have colons in their names. Please"
                    + " rename this variable.");
        }
    }

    int dataSize = variables.size();
    int laggedRows = data.getNumRows() - numLags;
    Knowledge knowledge = new Knowledge();
    Node[][] laggedNodes = new Node[numLags + 1][dataSize];
    List<Node> newVariables = new ArrayList<>((numLags + 1) * dataSize + 1);

    for (int lag = 0; lag <= numLags; lag++) {
        for (int col = 0; col < dataSize; col++) {
            Node node = variables.get(col);
            String varName = node.getName();
            Node laggedNode;
            String name = varName;

            if (lag != 0) {
                name = name + ":" + lag;
            }

            if (node instanceof ContinuousVariable) {
                laggedNode = new ContinuousVariable(name);
            } else if (node instanceof DiscreteVariable var) {
                laggedNode = new DiscreteVariable(var);
                laggedNode.setName(name);
            } else {
                throw new IllegalStateException("Node must be either continuous or discrete");
            }
            newVariables.add(laggedNode);
            laggedNode.setCenter(80 * col + 50, 80 * (numLags - lag) + 50);
            laggedNodes[lag][col] = laggedNode;
        }
    }

    // The generated names are all of the form "base" or "base:lag", with colon-free
    // bases guaranteed by the validation above, so getLag is exact here.
    for (Node node : newVariables) {
        knowledge.addToTier(numLags - getLag(node.getName()), node.getName());
    }

    DataSet laggedData = new BoxDataSet(new DoubleDataBox(laggedRows, newVariables.size()), newVariables);
    for (int lag = 0; lag <= numLags; lag++) {
        for (int col = 0; col < dataSize; col++) {
            for (int row = 0; row < laggedRows; row++) {
                Node laggedNode = laggedNodes[lag][col];
                if (laggedNode instanceof ContinuousVariable) {
                    double value = data.getDouble(row + numLags - lag, col);
                    laggedData.setDouble(row, col + lag * dataSize, value);
                } else {
                    int value = data.getInt(row + numLags - lag, col);
                    laggedData.setInt(row, col + lag * dataSize, value);
                }
            }
        }
    }

    knowledge.setDefaultToKnowledgeLayout(true);
    laggedData.setKnowledge(knowledge);
    return laggedData;
}

static Prepared prepare(Object algorithm, List<DataModel> dataSets, Parameters parameters) {
    int timeLag = parameters.getInt(Params.TIME_LAG);
    Prepared identity = new Prepared(dataSets, parameters, () -> {
    });

    if (timeLag <= 0) return identity;

    for (DataModel dataModel : dataSets) {
        if (!(dataModel instanceof DataSet)) return identity;
    }

    if (!(algorithm instanceof AcceptsKnowledge accepts)) {
        TetradLogger.getInstance().log("Bootstrapping with timeLag > 0 for an algorithm that does not " +
                                       "accept knowledge; rows will be resampled before lagging, which " +
                                       "destroys the time-series structure in each replicate.");
        return identity;
    }

    Knowledge base = accepts.getKnowledge();

    if (base == null || base.isEmpty()) {
        for (DataModel dataModel : dataSets) {
            Knowledge fromData = dataModel.getKnowledge();
            if (fromData == null || fromData.isEmpty()) continue;
            if (isBaseOnly(fromData)) {
                base = fromData;
                break;
            }
        }
    }

    if (base == null) base = new Knowledge();

    List<DataModel> lagged = new ArrayList<>(dataSets.size());
    Knowledge laggedKnowledge = null;

    for (DataModel dataModel : dataSets) {
        DataSet timeSeries = TsUtils.createLagData((DataSet) dataModel, timeLag, base);
        if (dataModel.getName() != null) timeSeries.setName(dataModel.getName());
        lagged.add(timeSeries);
        laggedKnowledge = timeSeries.getKnowledge();
    }

    Parameters lagFree = new Parameters(parameters);
    lagFree.set(Params.TIME_LAG, 0);

    final Knowledge original = accepts.getKnowledge();
    accepts.setKnowledge(laggedKnowledge);

    return new Prepared(lagged, lagFree, () -> accepts.setKnowledge(original == null ? new Knowledge() : original));
}

