	} else {
		int T = transitionNets.size();
		for (int t = 0; t < T; t++) {
			for(int n = 0; n < attributes.size(); n++) {
				score += sf.evaluate(o, transitionNets.get(t).getParents().get(n), n);
			}
		}
	}
	return score;
