            if (fScore != null) fScore.setThreadDataSets(null);
            if (fTest != null) fTest.setThreadDataSets(null);
        }
    };

    return bootstrapSearch(replicate, () -> runSearch(nominal, params), params, lagged);
} finally {
    if (originalScore != null) ((TakesScoreWrapper) this).setScoreWrapper(originalScore);
    if (originalTest != null) ((TakesIndependenceWrapper) this).setIndependenceWrapper(originalTest);
    prepared.restore().run();

    if (parameters.getInt(Params.TIME_LAG) > 0) {
        if (!(dataModel instanceof DataSet dataSet)) {
            throw new IllegalArgumentException("Expecting a data set for time lagging.");
        }

        DataSet timeSeries = TsUtils.createLagData(dataSet, parameters.getInt(Params.TIME_LAG), knowledge);
        if (dataSet.getName() != null) {
            timeSeries.setName(dataSet.getName());
        }
        dataModel = timeSeries;
        knowledge = timeSeries.getKnowledge();
    }

    edu.cmu.tetrad.search.Fci.ColliderRule colliderOrientationStyle = switch (parameters.getInt(Params.COLLIDER_ORIENTATION_STYLE)) {
        case 1 -> edu.cmu.tetrad.search.Fci.ColliderRule.SEPSETS;
        case 2 -> edu.cmu.tetrad.search.Fci.ColliderRule.CONSERVATIVE;
        case 3 -> edu.cmu.tetrad.search.Fci.ColliderRule.MAX_P;
        default -> throw new IllegalArgumentException("Invalid collider orientation style");
    };

    IndependenceTest test = getIndependenceWrapper().getTest(dataModel, parameters);
    test = new CachingIndependenceTest(test);

    edu.cmu.tetrad.search.Fci search = new edu.cmu.tetrad.search.Fci(test);
    search.setReplicatingGraph(parameters.getBoolean(Params.TIME_LAG_REPLICATING_GRAPH));
    search.setDepth(parameters.getInt(Params.DEPTH));
    search.setR0ColliderRule(colliderOrientationStyle);
    search.setKnowledge(this.knowledge);
    search.setMaxDiscriminatingPathLength(parameters.getInt(Params.MAX_DISCRIMINATING_PATH_LENGTH));
    search.setCompleteRuleSetUsed(parameters.getBoolean(Params.COMPLETE_RULE_SET_USED));
    search.setDoPossibleDsep(parameters.getBoolean(Params.DO_POSSIBLE_DSEP));
    search.setVerbose(parameters.getBoolean(Params.VERBOSE));
    search.setStable(parameters.getBoolean(Params.STABLE_FAS));
    search.setGuaranteePag(parameters.getBoolean(Params.GUARANTEE_PAG));
    search.setExcludeSelectionBias(parameters.getBoolean(Params.EXCLUDE_SELECTION_BIAS));

    Graph graph;
    double fdrQ = parameters.getDouble(Params.FDR_Q);

    if (fdrQ == 0.0) {
        graph = search.search();
    } else {
        boolean negativelyCorrelated = true;
        boolean verbose = parameters.getBoolean(Params.VERBOSE);
        double alpha = parameters.getDouble(Params.ALPHA);
        graph = IndTestFdrWrapper.doFdrLoop(search, negativelyCorrelated, alpha, fdrQ, verbose);
    }

    return graph;
}

/**
 * {@inheritDoc}
 * <p>
 * Runs the BOSS algorithm.
 */
@Override
protected Graph runSearch(DataModel dataModel, Parameters parameters) {
    long seed = parameters.getLong(Params.SEED);
    parameters.set(Params.NUM_THREADS, 4);

    if (parameters.getInt(Params.TIME_LAG) > 0) {
        if (!(dataModel instanceof DataSet dataSet)) {
            throw new IllegalArgumentException("Expecting a dataset for time lagging.");
        }

        DataSet timeSeries = TsUtils.createLagData(dataSet, parameters.getInt(Params.TIME_LAG), knowledge);
        if (dataModel.getName() != null) {
            timeSeries.setName(dataModel.getName());
        }
        dataModel = timeSeries;
        knowledge = timeSeries.getKnowledge();
    }

    Score myScore = this.score.getScore(dataModel, parameters);

    edu.cmu.tetrad.search.Boss boss = new edu.cmu.tetrad.search.Boss(myScore);

    boss.setUseBes(parameters.getBoolean(Params.USE_BES));
    boss.setNumStarts(parameters.getInt(Params.NUM_STARTS));
    boss.setUseIlsRestarts(parameters.getBoolean(Params.USE_ILS_RESTARTS));
    boss.setNumThreads(parameters.getInt(Params.NUM_THREADS));
    boss.setUseDataOrder(parameters.getBoolean(Params.USE_DATA_ORDER));
    boss.setVerbose(parameters.getBoolean(Params.VERBOSE));
    PermutationSearch permutationSearch = new PermutationSearch(boss);
    permutationSearch.setKnowledge(this.knowledge);
    permutationSearch.setSeed(seed);
    permutationSearch.setReplicatingGraph(parameters.getBoolean(Params.TIME_LAG_REPLICATING_GRAPH));
    try {
        Graph graph = permutationSearch.search(parameters.getBoolean(Params.OUTPUT_CPDAG));
        LogUtilsSearch.stampWithScore(graph, boss.getScore());
        LogUtilsSearch.stampWithBic(graph, dataModel);
        return graph;
    } catch (InterruptedException e) {
        throw new RuntimeException(e);
    }
}

